      WHEN 'palletizer' THEN 'palletizer'
      WHEN 'packaging_line' THEN 'packaging_line'
      ELSE NULLIF(trim(`work_center_type`), '')
    END AS `work_center_type`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_work_center
)
SELECT *
FROM typed
QUALIFY `work_center_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `work_center_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.manufacturing_bom ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_manufacturing_bom (
  CONSTRAINT `manufacturing_bom_id_not_null` EXPECT (`manufacturing_bom_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: manufacturing.manufacturing_bom typed and cleaned, one row per manufacturing_bom_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`manufacturing_bom_id`), '') AS BIGINT) AS `manufacturing_bom_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`primary_manufacturing_sku_id`), '') AS BIGINT) AS `primary_manufacturing_sku_id`,
    TRY_CAST(NULLIF(trim(`product_bom_id`), '') AS BIGINT) AS `product_bom_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    CASE WHEN lower(trim(`allergen_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`allergen_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `allergen_flag`,
    NULLIF(trim(`alternative_item_group`), '') AS `alternative_item_group`,
    TRY_CAST(NULLIF(trim(`alternative_item_priority`), '') AS INT) AS `alternative_item_priority`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    CASE WHEN lower(trim(`backflush_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`backflush_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `backflush_indicator`,
    TRY_CAST(NULLIF(trim(`base_quantity`), '') AS DECIMAL(18,6)) AS `base_quantity`,
    NULLIF(trim(`base_unit_of_measure`), '') AS `base_unit_of_measure`,
    NULLIF(trim(`bom_number`), '') AS `bom_number`,
    CASE lower(trim(`bom_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending' THEN 'pending'
      WHEN 'obsolete' THEN 'obsolete'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`bom_status`), '')
    END AS `bom_status`,
    CASE lower(trim(`bom_type`))
      WHEN 'production' THEN 'production'
      WHEN 'co-product' THEN 'co-product'
      WHEN 'phantom' THEN 'phantom'
      WHEN 'engineering' THEN 'engineering'
      WHEN 'planning' THEN 'planning'
      ELSE NULLIF(trim(`bom_type`), '')
    END AS `bom_type`,
    COALESCE(try_to_date(trim(`component_effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`component_effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`component_effective_end_date`) AS DATE)) AS `component_effective_end_date`,
    COALESCE(try_to_date(trim(`component_effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`component_effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`component_effective_start_date`) AS DATE)) AS `component_effective_start_date`,
    CASE lower(trim(`component_item_category`))
      WHEN 'stock' THEN 'stock'
      WHEN 'non-stock' THEN 'non-stock'
      WHEN 'phantom' THEN 'phantom'
      WHEN 'text' THEN 'text'
      WHEN 'variable_size' THEN 'variable_size'
      ELSE NULLIF(trim(`component_item_category`), '')
    END AS `component_item_category`,
    TRY_CAST(NULLIF(trim(`component_item_number`), '') AS INT) AS `component_item_number`,
    TRY_CAST(NULLIF(trim(`component_quantity`), '') AS DECIMAL(18,6)) AS `component_quantity`,
    NULLIF(trim(`component_unit_of_measure`), '') AS `component_unit_of_measure`,
    TRY_CAST(NULLIF(trim(`cost_allocation_percentage`), '') AS DECIMAL(5,2)) AS `cost_allocation_percentage`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`critical_component_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`critical_component_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `critical_component_flag`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    CASE WHEN lower(trim(`hazardous_material_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazardous_material_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazardous_material_flag`,
    NULLIF(trim(`inci_name`), '') AS `inci_name`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_days`), '') AS INT) AS `lead_time_days`,
    CASE lower(trim(`lot_size_requirement`))
      WHEN 'exact' THEN 'exact'
      WHEN 'minimum' THEN 'minimum'
      WHEN 'multiple' THEN 'multiple'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`lot_size_requirement`), '')
    END AS `lot_size_requirement`,
    TRY_CAST(NULLIF(trim(`minimum_lot_size`), '') AS DECIMAL(18,6)) AS `minimum_lot_size`,
    NULLIF(trim(`plm_system_reference`), '') AS `plm_system_reference`,
    NULLIF(trim(`regulatory_compliance_notes`), '') AS `regulatory_compliance_notes`,
    TRY_CAST(NULLIF(trim(`scrap_factor_percentage`), '') AS DECIMAL(5,2)) AS `scrap_factor_percentage`,
    NULLIF(trim(`sustainability_certification`), '') AS `sustainability_certification`,
    NULLIF(trim(`version`), '') AS `version`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_manufacturing_bom
)
SELECT *
FROM typed
QUALIFY `manufacturing_bom_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `manufacturing_bom_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.routing ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_routing (
  CONSTRAINT `routing_id_not_null` EXPECT (`routing_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: manufacturing.routing typed and cleaned, one row per routing_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`routing_id`), '') AS BIGINT) AS `routing_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`product_bom_id`), '') AS BIGINT) AS `product_bom_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    CASE lower(trim(`approval_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    TRY_CAST(NULLIF(trim(`base_quantity`), '') AS DECIMAL(15,3)) AS `base_quantity`,
    NULLIF(trim(`base_unit_of_measure`), '') AS `base_unit_of_measure`,
    TRY_CAST(NULLIF(trim(`changeover_time_minutes`), '') AS DECIMAL(10,2)) AS `changeover_time_minutes`,
    NULLIF(trim(`cost_currency_code`), '') AS `cost_currency_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`description`), '') AS `description`,
    TRY_CAST(NULLIF(trim(`expected_scrap_percentage`), '') AS DECIMAL(5,2)) AS `expected_scrap_percentage`,
    TRY_CAST(NULLIF(trim(`expected_yield_percentage`), '') AS DECIMAL(5,2)) AS `expected_yield_percentage`,
    CASE WHEN lower(trim(`gmp_critical_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_critical_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_critical_flag`,
    TRY_CAST(NULLIF(trim(`ipc_checkpoint_count`), '') AS INT) AS `ipc_checkpoint_count`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    CASE lower(trim(`lot_size_restriction`))
      WHEN 'none' THEN 'none'
      WHEN 'fixed' THEN 'fixed'
      WHEN 'minimum' THEN 'minimum'
      WHEN 'maximum' THEN 'maximum'
      WHEN 'multiple' THEN 'multiple'
      ELSE NULLIF(trim(`lot_size_restriction`), '')
    END AS `lot_size_restriction`,
    TRY_CAST(NULLIF(trim(`maximum_lot_size`), '') AS DECIMAL(15,3)) AS `maximum_lot_size`,
    TRY_CAST(NULLIF(trim(`minimum_lot_size`), '') AS DECIMAL(15,3)) AS `minimum_lot_size`,
    NULLIF(trim(`operation_sequence`), '') AS `operation_sequence`,
    NULLIF(trim(`production_scheduler_code`), '') AS `production_scheduler_code`,
    NULLIF(trim(`routing_number`), '') AS `routing_number`,
    CASE lower(trim(`routing_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'obsolete' THEN 'obsolete'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`routing_status`), '')
    END AS `routing_status`,
    CASE lower(trim(`routing_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'reference' THEN 'reference'
      WHEN 'rate' THEN 'rate'
      WHEN 'alternative' THEN 'alternative'
      WHEN 'special' THEN 'special'
      ELSE NULLIF(trim(`routing_type`), '')
    END AS `routing_type`,
    TRY_CAST(NULLIF(trim(`standard_cost_amount`), '') AS DECIMAL(15,2)) AS `standard_cost_amount`,
    TRY_CAST(NULLIF(trim(`total_labor_time_minutes`), '') AS DECIMAL(10,2)) AS `total_labor_time_minutes`,
    TRY_CAST(NULLIF(trim(`total_machine_time_minutes`), '') AS DECIMAL(10,2)) AS `total_machine_time_minutes`,
    TRY_CAST(NULLIF(trim(`total_setup_time_minutes`), '') AS DECIMAL(10,2)) AS `total_setup_time_minutes`,
    TRY_CAST(NULLIF(trim(`total_standard_lead_time_hours`), '') AS DECIMAL(10,2)) AS `total_standard_lead_time_hours`,
    COALESCE(try_to_date(trim(`valid_from_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_from_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_from_date`) AS DATE)) AS `valid_from_date`,
    COALESCE(try_to_date(trim(`valid_to_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_to_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_to_date`) AS DATE)) AS `valid_to_date`,
    NULLIF(trim(`version`), '') AS `version`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_routing
)
SELECT *
FROM typed
QUALIFY `routing_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `routing_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.production_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_production_order (
  CONSTRAINT `production_order_id_not_null` EXPECT (`production_order_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `order_quantity_not_negative` EXPECT (`order_quantity` IS NULL OR `order_quantity` >= 0),
  CONSTRAINT `confirmed_quantity_not_negative` EXPECT (`confirmed_quantity` IS NULL OR `confirmed_quantity` >= 0),
  CONSTRAINT `scrap_quantity_not_negative` EXPECT (`scrap_quantity` IS NULL OR `scrap_quantity` >= 0),
  CONSTRAINT `planned_cost_not_negative` EXPECT (`planned_cost` IS NULL OR `planned_cost` >= 0),
  CONSTRAINT `actual_cost_not_negative` EXPECT (`actual_cost` IS NULL OR `actual_cost` >= 0)
)
COMMENT 'Silver: manufacturing.production_order typed and cleaned, one row per production_order_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`inspection_plan_id`), '') AS BIGINT) AS `inspection_plan_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_bom_id`), '') AS BIGINT) AS `manufacturing_bom_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`production_line_id`), '') AS BIGINT) AS `production_line_id`,
    TRY_CAST(NULLIF(trim(`routing_id`), '') AS BIGINT) AS `routing_id`,
    TRY_CAST(NULLIF(trim(`sales_order_id`), '') AS BIGINT) AS `sales_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`actual_cost`), '') AS DECIMAL(15,2)) AS `actual_cost`,
    COALESCE(try_to_timestamp(trim(`actual_finish_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_finish_timestamp`) AS TIMESTAMP)) AS `actual_finish_timestamp`,
    COALESCE(try_to_timestamp(trim(`actual_start_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_start_timestamp`) AS TIMESTAMP)) AS `actual_start_timestamp`,
    NULLIF(trim(`batch_number`), '') AS `batch_number`,
    TRY_CAST(NULLIF(trim(`changeover_time_minutes`), '') AS INT) AS `changeover_time_minutes`,
    TRY_CAST(NULLIF(trim(`confirmed_quantity`), '') AS DECIMAL(15,3)) AS `confirmed_quantity`,
    NULLIF(trim(`cost_object`), '') AS `cost_object`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`downtime_minutes`), '') AS INT) AS `downtime_minutes`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    NULLIF(trim(`inspection_lot_number`), '') AS `inspection_lot_number`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`material_number`), '') AS `material_number`,
    NULLIF(trim(`mrp_controller`), '') AS `mrp_controller`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`oee_percentage`), '') AS DECIMAL(5,2)) AS `oee_percentage`,
    NULLIF(trim(`order_number`), '') AS `order_number`,
    TRY_CAST(NULLIF(trim(`order_quantity`), '') AS DECIMAL(15,3)) AS `order_quantity`,
    NULLIF(trim(`order_status`), '') AS `order_status`,
    CASE lower(trim(`order_type`))
      WHEN 'pp01' THEN 'PP01'
      WHEN 'pp03' THEN 'PP03'
      WHEN 'pp05' THEN 'PP05'
      WHEN 'pp10' THEN 'PP10'
      WHEN 'pp20' THEN 'PP20'
      ELSE NULLIF(trim(`order_type`), '')
    END AS `order_type`,
    TRY_CAST(NULLIF(trim(`planned_cost`), '') AS DECIMAL(15,2)) AS `planned_cost`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    CASE lower(trim(`priority`))
      WHEN '1' THEN '1'
      WHEN '2' THEN '2'
      WHEN '3' THEN '3'
      WHEN '4' THEN '4'
      WHEN '5' THEN '5'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    NULLIF(trim(`production_supervisor`), '') AS `production_supervisor`,
    NULLIF(trim(`production_version`), '') AS `production_version`,
    CASE WHEN lower(trim(`quality_inspection_required`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_inspection_required`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_inspection_required`,
    NULLIF(trim(`released_by`), '') AS `released_by`,
    COALESCE(try_to_timestamp(trim(`released_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`released_timestamp`) AS TIMESTAMP)) AS `released_timestamp`,
    COALESCE(try_to_date(trim(`scheduled_finish_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_finish_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_finish_date`) AS DATE)) AS `scheduled_finish_date`,
    COALESCE(try_to_date(trim(`scheduled_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_start_date`) AS DATE)) AS `scheduled_start_date`,
    TRY_CAST(NULLIF(trim(`scrap_quantity`), '') AS DECIMAL(15,3)) AS `scrap_quantity`,
    CASE lower(trim(`settlement_rule`))
      WHEN 'ful' THEN 'FUL'
      WHEN 'par' THEN 'PAR'
      WHEN 'per' THEN 'PER'
      ELSE NULLIF(trim(`settlement_rule`), '')
    END AS `settlement_rule`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`yield_percentage`), '') AS DECIMAL(5,2)) AS `yield_percentage`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_production_order
)
SELECT *
FROM typed
QUALIFY `production_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `production_order_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.batch_record ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_batch_record (
  CONSTRAINT `batch_record_id_not_null` EXPECT (`batch_record_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `scrap_quantity_not_negative` EXPECT (`scrap_quantity` IS NULL OR `scrap_quantity` >= 0),
  CONSTRAINT `rework_quantity_not_negative` EXPECT (`rework_quantity` IS NULL OR `rework_quantity` >= 0)
)
COMMENT 'Silver: manufacturing.batch_record typed and cleaned, one row per batch_record_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`formulation_id`), '') AS BIGINT) AS `formulation_id`,
    TRY_CAST(NULLIF(trim(`goods_receipt_id`), '') AS BIGINT) AS `goods_receipt_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_bom_id`), '') AS BIGINT) AS `manufacturing_bom_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`production_line_id`), '') AS BIGINT) AS `production_line_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`routing_id`), '') AS BIGINT) AS `routing_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`actual_cost_amount`), '') AS DECIMAL(18,2)) AS `actual_cost_amount`,
    NULLIF(trim(`batch_number`), '') AS `batch_number`,
    TRY_CAST(NULLIF(trim(`batch_size_actual`), '') AS DECIMAL(18,3)) AS `batch_size_actual`,
    TRY_CAST(NULLIF(trim(`batch_size_planned`), '') AS DECIMAL(18,3)) AS `batch_size_planned`,
    CASE lower(trim(`batch_status`))
      WHEN 'in_process' THEN 'in_process'
      WHEN 'released' THEN 'released'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'quarantine' THEN 'quarantine'
      WHEN 'recalled' THEN 'recalled'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`batch_status`), '')
    END AS `batch_status`,
    NULLIF(trim(`bom_version`), '') AS `bom_version`,
    TRY_CAST(NULLIF(trim(`changeover_minutes`), '') AS INT) AS `changeover_minutes`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`downtime_minutes`), '') AS INT) AS `downtime_minutes`,
    TRY_CAST(NULLIF(trim(`electronic_signature_count`), '') AS INT) AS `electronic_signature_count`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    TRY_CAST(NULLIF(trim(`gmp_deviation_count`), '') AS INT) AS `gmp_deviation_count`,
    CASE WHEN lower(trim(`gmp_deviation_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_deviation_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_deviation_flag`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    CASE WHEN lower(trim(`lot_genealogy_complete_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`lot_genealogy_complete_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `lot_genealogy_complete_flag`,
    COALESCE(try_to_date(trim(`manufacturing_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacturing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacturing_date`) AS DATE)) AS `manufacturing_date`,
    COALESCE(try_to_timestamp(trim(`manufacturing_end_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`manufacturing_end_timestamp`) AS TIMESTAMP)) AS `manufacturing_end_timestamp`,
    COALESCE(try_to_timestamp(trim(`manufacturing_start_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`manufacturing_start_timestamp`) AS TIMESTAMP)) AS `manufacturing_start_timestamp`,
    TRY_CAST(NULLIF(trim(`oee_percentage`), '') AS DECIMAL(5,2)) AS `oee_percentage`,
    CASE WHEN lower(trim(`quality_release_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_release_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_release_flag`,
    COALESCE(try_to_timestamp(trim(`quality_release_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`quality_release_timestamp`) AS TIMESTAMP)) AS `quality_release_timestamp`,
    CASE WHEN lower(trim(`recall_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`recall_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `recall_flag`,
    COALESCE(try_to_date(trim(`recall_initiated_date`), 'yyyy-MM-dd'), try_to_date(trim(`recall_initiated_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`recall_initiated_date`) AS DATE)) AS `recall_initiated_date`,
    CASE WHEN lower(trim(`record_locked_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`record_locked_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `record_locked_flag`,
    CASE WHEN lower(trim(`regulatory_hold_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_hold_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_hold_flag`,
    TRY_CAST(NULLIF(trim(`rework_quantity`), '') AS DECIMAL(18,3)) AS `rework_quantity`,
    NULLIF(trim(`routing_version`), '') AS `routing_version`,
    TRY_CAST(NULLIF(trim(`scrap_quantity`), '') AS DECIMAL(18,3)) AS `scrap_quantity`,
    TRY_CAST(NULLIF(trim(`shelf_life_days`), '') AS INT) AS `shelf_life_days`,
    TRY_CAST(NULLIF(trim(`standard_cost_amount`), '') AS DECIMAL(18,2)) AS `standard_cost_amount`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    NULLIF(trim(`veeva_vault_document_reference`), '') AS `veeva_vault_document_reference`,
    TRY_CAST(NULLIF(trim(`yield_percentage`), '') AS DECIMAL(5,2)) AS `yield_percentage`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_batch_record
)
SELECT *
FROM typed
QUALIFY `batch_record_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `batch_record_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.yield_record ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_yield_record (
  CONSTRAINT `yield_record_id_not_null` EXPECT (`yield_record_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `input_quantity_not_negative` EXPECT (`input_quantity` IS NULL OR `input_quantity` >= 0),
  CONSTRAINT `output_quantity_not_negative` EXPECT (`output_quantity` IS NULL OR `output_quantity` >= 0),
  CONSTRAINT `scrap_quantity_not_negative` EXPECT (`scrap_quantity` IS NULL OR `scrap_quantity` >= 0)
)
COMMENT 'Silver: manufacturing.yield_record typed and cleaned, one row per yield_record_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`yield_record_id`), '') AS BIGINT) AS `yield_record_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`production_line_id`), '') AS BIGINT) AS `production_line_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`work_center_id`), '') AS BIGINT) AS `work_center_id`,
    TRY_CAST(NULLIF(trim(`actual_yield_percentage`), '') AS DECIMAL(5,2)) AS `actual_yield_percentage`,
    NULLIF(trim(`comments`), '') AS `comments`,
    NULLIF(trim(`cost_center_code`), '') AS `cost_center_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`erp_document_number`), '') AS `erp_document_number`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    TRY_CAST(NULLIF(trim(`input_quantity`), '') AS DECIMAL(18,4)) AS `input_quantity`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_timestamp(trim(`measurement_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`measurement_timestamp`) AS TIMESTAMP)) AS `measurement_timestamp`,
    NULLIF(trim(`mes_transaction_reference`), '') AS `mes_transaction_reference`,
    COALESCE(try_to_timestamp(trim(`operation_end_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`operation_end_timestamp`) AS TIMESTAMP)) AS `operation_end_timestamp`,
    COALESCE(try_to_timestamp(trim(`operation_start_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`operation_start_timestamp`) AS TIMESTAMP)) AS `operation_start_timestamp`,
    TRY_CAST(NULLIF(trim(`output_quantity`), '') AS DECIMAL(18,4)) AS `output_quantity`,
    NULLIF(trim(`quality_inspection_lot_number`), '') AS `quality_inspection_lot_number`,
    TRY_CAST(NULLIF(trim(`rework_quantity`), '') AS DECIMAL(18,4)) AS `rework_quantity`,
    NULLIF(trim(`routing_operation_number`), '') AS `routing_operation_number`,
    TRY_CAST(NULLIF(trim(`scrap_quantity`), '') AS DECIMAL(18,4)) AS `scrap_quantity`,
    CASE lower(trim(`shift_code`))
      WHEN 'shift_1' THEN 'SHIFT_1'
      WHEN 'shift_2' THEN 'SHIFT_2'
      WHEN 'shift_3' THEN 'SHIFT_3'
      WHEN 'day' THEN 'DAY'
      WHEN 'night' THEN 'NIGHT'
      WHEN 'weekend' THEN 'WEEKEND'
      ELSE NULLIF(trim(`shift_code`), '')
    END AS `shift_code`,
    TRY_CAST(NULLIF(trim(`standard_cost_per_unit`), '') AS DECIMAL(18,4)) AS `standard_cost_per_unit`,
    TRY_CAST(NULLIF(trim(`theoretical_yield_percentage`), '') AS DECIMAL(5,2)) AS `theoretical_yield_percentage`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    NULLIF(trim(`yield_loss_reason_code`), '') AS `yield_loss_reason_code`,
    NULLIF(trim(`yield_loss_reason_description`), '') AS `yield_loss_reason_description`,
    TRY_CAST(NULLIF(trim(`yield_variance_cost_impact`), '') AS DECIMAL(18,2)) AS `yield_variance_cost_impact`,
    TRY_CAST(NULLIF(trim(`yield_variance_percentage`), '') AS DECIMAL(5,2)) AS `yield_variance_percentage`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_yield_record
)
SELECT *
FROM typed
QUALIFY `yield_record_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `yield_record_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.production_confirmation ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_production_confirmation (
  CONSTRAINT `production_confirmation_id_not_null` EXPECT (`production_confirmation_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `confirmed_yield_quantity_not_negative` EXPECT (`confirmed_yield_quantity` IS NULL OR `confirmed_yield_quantity` >= 0),
  CONSTRAINT `confirmed_scrap_quantity_not_negative` EXPECT (`confirmed_scrap_quantity` IS NULL OR `confirmed_scrap_quantity` >= 0)
)
COMMENT 'Silver: manufacturing.production_confirmation typed and cleaned, one row per production_confirmation_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`production_confirmation_id`), '') AS BIGINT) AS `production_confirmation_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`routing_id`), '') AS BIGINT) AS `routing_id`,
    TRY_CAST(NULLIF(trim(`sales_order_id`), '') AS BIGINT) AS `sales_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`work_center_id`), '') AS BIGINT) AS `work_center_id`,
    NULLIF(trim(`activity_type`), '') AS `activity_type`,
    COALESCE(try_to_timestamp(trim(`actual_end_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_end_datetime`) AS TIMESTAMP)) AS `actual_end_datetime`,
    TRY_CAST(NULLIF(trim(`actual_labor_time_minutes`), '') AS DECIMAL(10,2)) AS `actual_labor_time_minutes`,
    TRY_CAST(NULLIF(trim(`actual_machine_time_minutes`), '') AS DECIMAL(10,2)) AS `actual_machine_time_minutes`,
    TRY_CAST(NULLIF(trim(`actual_setup_time_minutes`), '') AS DECIMAL(10,2)) AS `actual_setup_time_minutes`,
    COALESCE(try_to_timestamp(trim(`actual_start_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_start_datetime`) AS TIMESTAMP)) AS `actual_start_datetime`,
    NULLIF(trim(`confirmation_notes`), '') AS `confirmation_notes`,
    COALESCE(try_to_timestamp(trim(`confirmation_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`confirmation_timestamp`) AS TIMESTAMP)) AS `confirmation_timestamp`,
    CASE lower(trim(`confirmation_type`))
      WHEN 'partial' THEN 'partial'
      WHEN 'final' THEN 'final'
      WHEN 'milestone' THEN 'milestone'
      WHEN 'rework' THEN 'rework'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`confirmation_type`), '')
    END AS `confirmation_type`,
    TRY_CAST(NULLIF(trim(`confirmed_scrap_quantity`), '') AS DECIMAL(18,3)) AS `confirmed_scrap_quantity`,
    TRY_CAST(NULLIF(trim(`confirmed_yield_quantity`), '') AS DECIMAL(18,3)) AS `confirmed_yield_quantity`,
    TRY_CAST(NULLIF(trim(`downtime_minutes`), '') AS DECIMAL(10,2)) AS `downtime_minutes`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`mes_transaction_reference`), '') AS `mes_transaction_reference`,
    TRY_CAST(NULLIF(trim(`oee_availability_percent`), '') AS DECIMAL(5,2)) AS `oee_availability_percent`,
    TRY_CAST(NULLIF(trim(`oee_performance_percent`), '') AS DECIMAL(5,2)) AS `oee_performance_percent`,
    TRY_CAST(NULLIF(trim(`oee_quality_percent`), '') AS DECIMAL(5,2)) AS `oee_quality_percent`,
    NULLIF(trim(`operation_number`), '') AS `operation_number`,
    CASE lower(trim(`operation_status`))
      WHEN 'open' THEN 'open'
      WHEN 'in_progress' THEN 'in_progress'
      WHEN 'completed' THEN 'completed'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'on_hold' THEN 'on_hold'
      ELSE NULLIF(trim(`operation_status`), '')
    END AS `operation_status`,
    COALESCE(try_to_date(trim(`posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`posting_date`) AS DATE)) AS `posting_date`,
    CASE WHEN lower(trim(`quality_inspection_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_inspection_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_inspection_required_flag`,
    CASE WHEN lower(trim(`reversal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`reversal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `reversal_flag`,
    NULLIF(trim(`reversal_reason_code`), '') AS `reversal_reason_code`,
    CASE WHEN lower(trim(`rework_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`rework_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `rework_flag`,
    COALESCE(try_to_timestamp(trim(`scheduled_end_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`scheduled_end_datetime`) AS TIMESTAMP)) AS `scheduled_end_datetime`,
    COALESCE(try_to_timestamp(trim(`scheduled_start_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`scheduled_start_datetime`) AS TIMESTAMP)) AS `scheduled_start_datetime`,
    NULLIF(trim(`shift_code`), '') AS `shift_code`,
    CASE lower(trim(`source_system_code`))
      WHEN 'sap_pp' THEN 'SAP_PP'
      WHEN 'opcenter_mes' THEN 'OPCENTER_MES'
      WHEN 'manual' THEN 'MANUAL'
      ELSE NULLIF(trim(`source_system_code`), '')
    END AS `source_system_code`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    NULLIF(trim(`variance_reason_code`), '') AS `variance_reason_code`,
    NULLIF(trim(`work_order_number`), '') AS `work_order_number`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_production_confirmation
)
SELECT *
FROM typed
QUALIFY `production_confirmation_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `production_confirmation_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.planned_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_planned_order (
  CONSTRAINT `planned_order_id_not_null` EXPECT (`planned_order_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: manufacturing.planned_order typed and cleaned, one row per planned_order_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`planned_order_id`), '') AS BIGINT) AS `planned_order_id`,
    TRY_CAST(NULLIF(trim(`converted_production_order_id`), '') AS BIGINT) AS `converted_production_order_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_bom_id`), '') AS BIGINT) AS `manufacturing_bom_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`routing_id`), '') AS BIGINT) AS `routing_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`target_distribution_facility_id`), '') AS BIGINT) AS `target_distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    COALESCE(try_to_date(trim(`availability_date`), 'yyyy-MM-dd'), try_to_date(trim(`availability_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`availability_date`) AS DATE)) AS `availability_date`,
    COALESCE(try_to_date(trim(`conversion_date`), 'yyyy-MM-dd'), try_to_date(trim(`conversion_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`conversion_date`) AS DATE)) AS `conversion_date`,
    CASE lower(trim(`conversion_status`))
      WHEN 'not_converted' THEN 'NOT_CONVERTED'
      WHEN 'partially_converted' THEN 'PARTIALLY_CONVERTED'
      WHEN 'fully_converted' THEN 'FULLY_CONVERTED'
      ELSE NULLIF(trim(`conversion_status`), '')
    END AS `conversion_status`,
    NULLIF(trim(`created_by_user`), '') AS `created_by_user`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`demand_source_reference`), '') AS `demand_source_reference`,
    CASE lower(trim(`demand_source_type`))
      WHEN 'forecast' THEN 'FORECAST'
      WHEN 'customer_order' THEN 'CUSTOMER_ORDER'
      WHEN 'stock_transfer' THEN 'STOCK_TRANSFER'
      WHEN 'safety_stock' THEN 'SAFETY_STOCK'
      WHEN 'promotion' THEN 'PROMOTION'
      ELSE NULLIF(trim(`demand_source_type`), '')
    END AS `demand_source_type`,
    NULLIF(trim(`exception_message_code`), '') AS `exception_message_code`,
    NULLIF(trim(`exception_message_text`), '') AS `exception_message_text`,
    COALESCE(try_to_date(trim(`firming_date`), 'yyyy-MM-dd'), try_to_date(trim(`firming_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`firming_date`) AS DATE)) AS `firming_date`,
    CASE WHEN lower(trim(`firming_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`firming_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `firming_indicator`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    NULLIF(trim(`ibp_plan_version`), '') AS `ibp_plan_version`,
    NULLIF(trim(`last_modified_by_user`), '') AS `last_modified_by_user`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    CASE lower(trim(`lot_size_key`))
      WHEN 'ex' THEN 'EX'
      WHEN 'hb' THEN 'HB'
      WHEN 'fx' THEN 'FX'
      WHEN 'pd' THEN 'PD'
      WHEN 'wm' THEN 'WM'
      ELSE NULLIF(trim(`lot_size_key`), '')
    END AS `lot_size_key`,
    NULLIF(trim(`mrp_controller`), '') AS `mrp_controller`,
    TRY_CAST(NULLIF(trim(`mrp_run_code`), '') AS BIGINT) AS `mrp_run_code`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`order_number`), '') AS `order_number`,
    CASE lower(trim(`order_status`))
      WHEN 'draft' THEN 'DRAFT'
      WHEN 'firmed' THEN 'FIRMED'
      WHEN 'released' THEN 'RELEASED'
      WHEN 'converted' THEN 'CONVERTED'
      WHEN 'deleted' THEN 'DELETED'
      WHEN 'cancelled' THEN 'CANCELLED'
      ELSE NULLIF(trim(`order_status`), '')
    END AS `order_status`,
    CASE lower(trim(`order_type`))
      WHEN 'mps' THEN 'MPS'
      WHEN 'mrp' THEN 'MRP'
      WHEN 'cbp' THEN 'CBP'
      WHEN 'manual' THEN 'MANUAL'
      WHEN 'forecast' THEN 'FORECAST'
      WHEN 'safety' THEN 'SAFETY'
      ELSE NULLIF(trim(`order_type`), '')
    END AS `order_type`,
    TRY_CAST(NULLIF(trim(`planned_quantity`), '') AS DECIMAL(18,3)) AS `planned_quantity`,
    NULLIF(trim(`planning_period`), '') AS `planning_period`,
    NULLIF(trim(`planning_strategy_group`), '') AS `planning_strategy_group`,
    CASE lower(trim(`priority_code`))
      WHEN 'low' THEN 'LOW'
      WHEN 'normal' THEN 'NORMAL'
      WHEN 'high' THEN 'HIGH'
      WHEN 'urgent' THEN 'URGENT'
      ELSE NULLIF(trim(`priority_code`), '')
    END AS `priority_code`,
    CASE lower(trim(`procurement_type`))
      WHEN 'in_house' THEN 'IN_HOUSE'
      WHEN 'external' THEN 'EXTERNAL'
      WHEN 'both' THEN 'BOTH'
      ELSE NULLIF(trim(`procurement_type`), '')
    END AS `procurement_type`,
    NULLIF(trim(`production_version`), '') AS `production_version`,
    TRY_CAST(NULLIF(trim(`reorder_point_quantity`), '') AS DECIMAL(18,3)) AS `reorder_point_quantity`,
    TRY_CAST(NULLIF(trim(`safety_stock_quantity`), '') AS DECIMAL(18,3)) AS `safety_stock_quantity`,
    NULLIF(trim(`schedule_version`), '') AS `schedule_version`,
    COALESCE(try_to_date(trim(`scheduled_finish_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_finish_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_finish_date`) AS DATE)) AS `scheduled_finish_date`,
    COALESCE(try_to_date(trim(`scheduled_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_start_date`) AS DATE)) AS `scheduled_start_date`,
    NULLIF(trim(`sop_cycle_reference`), '') AS `sop_cycle_reference`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_planned_order
)
SELECT *
FROM typed
QUALIFY `planned_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `planned_order_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- manufacturing.equipment ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.manufacturing_equipment (
  CONSTRAINT `equipment_id_not_null` EXPECT (`equipment_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: manufacturing.equipment typed and cleaned, one row per equipment_id (latest _ingested_at wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`equipment_id`), '') AS BIGINT) AS `equipment_id`,
    TRY_CAST(NULLIF(trim(`acquisition_purchase_order_id`), '') AS BIGINT) AS `acquisition_purchase_order_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`parent_equipment_id`), '') AS BIGINT) AS `parent_equipment_id`,
    TRY_CAST(NULLIF(trim(`production_line_id`), '') AS BIGINT) AS `production_line_id`,
    TRY_CAST(NULLIF(trim(`work_center_id`), '') AS BIGINT) AS `work_center_id`,
    TRY_CAST(NULLIF(trim(`acquisition_cost`), '') AS DECIMAL(12,2)) AS `acquisition_cost`,
    NULLIF(trim(`asset_tag`), '') AS `asset_tag`,
    COALESCE(try_to_date(trim(`calibration_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`calibration_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`calibration_due_date`) AS DATE)) AS `calibration_due_date`,
    NULLIF(trim(`capacity_units`), '') AS `capacity_units`,
    TRY_CAST(NULLIF(trim(`capacity_value`), '') AS DECIMAL(12,2)) AS `capacity_value`,
    CASE WHEN lower(trim(`compliance_gmp`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`compliance_gmp`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `compliance_gmp`,
    NULLIF(trim(`currency`), '') AS `currency`,
    NULLIF(trim(`department`), '') AS `department`,
    COALESCE(try_to_date(trim(`depreciation_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`depreciation_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`depreciation_end_date`) AS DATE)) AS `depreciation_end_date`,
    NULLIF(trim(`depreciation_method`), '') AS `depreciation_method`,
    COALESCE(try_to_date(trim(`depreciation_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`depreciation_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`depreciation_start_date`) AS DATE)) AS `depreciation_start_date`,
    NULLIF(trim(`description`), '') AS `description`,
    TRY_CAST(NULLIF(trim(`energy_consumption_kwh`), '') AS DECIMAL(12,2)) AS `energy_consumption_kwh`,
    NULLIF(trim(`equipment_status`), '') AS `equipment_status`,
    NULLIF(trim(`equipment_type`), '') AS `equipment_type`,
    NULLIF(trim(`hazard_classification`), '') AS `hazard_classification`,
    COALESCE(try_to_date(trim(`installation_date`), 'yyyy-MM-dd'), try_to_date(trim(`installation_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`installation_date`) AS DATE)) AS `installation_date`,
    COALESCE(try_to_date(trim(`last_calibration_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_calibration_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_calibration_date`) AS DATE)) AS `last_calibration_date`,
    COALESCE(try_to_date(trim(`last_maintenance_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_maintenance_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_maintenance_date`) AS DATE)) AS `last_maintenance_date`,
    NULLIF(trim(`location_code`), '') AS `location_code`,
    TRY_CAST(NULLIF(trim(`maintenance_cost`), '') AS DECIMAL(12,2)) AS `maintenance_cost`,
    TRY_CAST(NULLIF(trim(`maintenance_frequency_days`), '') AS INT) AS `maintenance_frequency_days`,
    NULLIF(trim(`manufacturer`), '') AS `manufacturer`,
    NULLIF(trim(`model_number`), '') AS `model_number`,
    TRY_CAST(NULLIF(trim(`mtbf_hours`), '') AS DECIMAL(10,2)) AS `mtbf_hours`,
    TRY_CAST(NULLIF(trim(`mttr_hours`), '') AS DECIMAL(10,2)) AS `mttr_hours`,
    NULLIF(trim(`name`), '') AS `name`,
    COALESCE(try_to_date(trim(`next_maintenance_due`), 'yyyy-MM-dd'), try_to_date(trim(`next_maintenance_due`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_maintenance_due`) AS DATE)) AS `next_maintenance_due`,
    TRY_CAST(NULLIF(trim(`oee_actual`), '') AS DECIMAL(5,2)) AS `oee_actual`,
    TRY_CAST(NULLIF(trim(`oee_target`), '') AS DECIMAL(5,2)) AS `oee_target`,
    TRY_CAST(NULLIF(trim(`power_rating_kw`), '') AS DECIMAL(10,2)) AS `power_rating_kw`,
    COALESCE(try_to_date(trim(`purchase_date`), 'yyyy-MM-dd'), try_to_date(trim(`purchase_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`purchase_date`) AS DATE)) AS `purchase_date`,
    NULLIF(trim(`safety_rating`), '') AS `safety_rating`,
    NULLIF(trim(`serial_number`), '') AS `serial_number`,
    TRY_CAST(NULLIF(trim(`total_usage_hours`), '') AS DECIMAL(10,2)) AS `total_usage_hours`,
    TRY_CAST(NULLIF(trim(`voltage`), '') AS DECIMAL(10,2)) AS `voltage`,
    COALESCE(try_to_date(trim(`warranty_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`warranty_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`warranty_end_date`) AS DATE)) AS `warranty_end_date`,
    COALESCE(try_to_date(trim(`warranty_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`warranty_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`warranty_start_date`) AS DATE)) AS `warranty_start_date`,
    TRY_CAST(NULLIF(trim(`weight_kg`), '') AS DECIMAL(10,2)) AS `weight_kg`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.manufacturing_equipment
)
SELECT *
FROM typed
QUALIFY `equipment_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `equipment_id` ORDER BY _ingested_at DESC) = 1;
